"""risk's boundary types: returns, volatility, the summary, the drawdown and the report."""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns: `dates` are the prices' dates after the first, `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """One ticker's whole-period statistics and its last rolling volatility."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """The worst fall from a peak: `depth` <= 0; with no fall both dates are the first date."""

    ticker: str
    depth: float
    peak_date: str
    trough_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted, the same rows as the file."""

    path: str
    rows: tuple[Mapping[str, object], ...]
